//! Contracts of the volatility family, from `tests/fixtures/contract_volatility.txt`.
//!
//! Generated by `reference/kestrel_reference/fixtures/contract_volatility.py`; the conventions it
//! assumes where the type documentation leaves something open (undocumented alert strengths,
//! the first bar of the stop ratchets) are listed in that module's docstring.

use super::{assert_holds, assert_rejected, Coverage, Status};
use crate::common::contract::{load, ContractCase};
use kestrel_chartkit::IndicatorUnit;

const FIXTURE: &str = include_str!("../fixtures/contract_volatility.txt");

fn case(name: &str, indicator: &str, unit: IndicatorUnit) -> ContractCase {
    load(FIXTURE, name, indicator, unit)
}

/// Indicators of this family whose contract is not yet written. Moved into [`COVERAGE`] once
/// their cases exist; a name in neither list fails the matrix.
pub const PENDING: &[&str] = &[];

pub const COVERAGE: &[Coverage] = &[
    Coverage::full("adx"),
    Coverage::full("dmi"),
    Coverage::full("aroon"),
    Coverage::full("vortex"),
    Coverage::full("choppiness"),
    Coverage {
        indicator: "relative_volatility",
        values: Status::Partial("close variant only; high_low is reachable through build_typed"),
        alerts: Status::Specified,
        configuration: Status::Specified,
    },
    Coverage::full("ulcer_index"),
    Coverage::full("true_range"),
    Coverage::full("historical_volatility"),
    Coverage::full("garman_klass"),
    Coverage::full("mass_index"),
    Coverage::full("chande_kroll"),
    Coverage::full("chandelier_exit"),
    Coverage {
        indicator: "adaptive_chandelier",
        values: Status::Partial(
            "registry surface only: high/low extremes and the adaptive multiplier are not reachable through build_checked",
        ),
        alerts: Status::Specified,
        configuration: Status::Specified,
    },
    Coverage::full("vix_fix"),
    Coverage::full("efficiency"),
    Coverage::full("volatility_regime"),
];

// --- ADX -------------------------------------------------------------------------------------

#[test]
fn adx_defaults() {
    assert_holds(&case("adx_defaults", "adx", IndicatorUnit::Ratio));
}

#[test]
fn adx_short() {
    assert_holds(&case("adx_short", "adx", IndicatorUnit::Ratio));
}

#[test]
fn adx_zero_level() {
    assert_holds(&case("adx_zero_level", "adx", IndicatorUnit::Ratio));
}

#[test]
fn adx_rejects_invalid_configuration() {
    assert_rejected("adx", &[("di_len", 0.0)]);
    assert_rejected("adx", &[("adx_smooth", 0.0)]);
    assert_rejected("adx", &[("di_len", 2.5)]);
    assert_rejected("adx", &[("level_weak", 120.0)]);
    assert_rejected("adx", &[("level_weak", -1.0)]);
    assert_rejected("adx", &[("sig_len", 3.0)]);
    assert_rejected("adx", &[("period", 14.0)]);
}

